-- Convert property_link IDs from Prisma CUID text values to PostgreSQL UUIDs.
BEGIN;

-- Keep existing rows while replacing each CUID with a UUID generated by PostgreSQL.
CREATE TEMP TABLE _property_link_id_uuid_map (
  old_id TEXT PRIMARY KEY,
  new_id UUID NOT NULL DEFAULT gen_random_uuid()
) ON COMMIT DROP;

INSERT INTO _property_link_id_uuid_map (old_id)
SELECT id::text
FROM public.property_link;

UPDATE public.property_link AS target
SET id = mapping.new_id::text
FROM _property_link_id_uuid_map AS mapping
WHERE target.id::text = mapping.old_id;

ALTER TABLE public.property_link
  ALTER COLUMN id TYPE UUID USING id::uuid,
  ALTER COLUMN id SET DEFAULT gen_random_uuid();

COMMIT;
